function Catalogue.Get(enemyId) return Catalogue.entries[tonumber(enemyId)] end
function Catalogue.CardIdForEnemy(enemyId) local entry = Catalogue.Get(enemyId); return entry and entry.cardId or nil end
function Catalogue.RequiresStaticCard(enemyId) local entry = Catalogue.Get(enemyId); return entry and entry.staticCard == true or false end
